/**
 * Represents a blog author.
 */
export interface BlogAuthor {
  /**
   * Unique identifier for the author.
   */
  id: string;
  /**
   * Display name of the author.
   */
  name: string;
  /**
   * Optional URL to the author's avatar image.
   */
  avatarUrl?: string;
  /**
   * Optional short biography of the author.
   */
  bio?: string;
}

/**
 * Represents a blog category.
 */
export interface BlogCategory {
  /**
   * Unique identifier for the category.
   */
  id: string;
  /**
   * Human-readable category name.
   */
  name: string;
  /**
   * URL-friendly slug for the category.
   */
  slug: string;
}

/**
 * Content block for paragraph text.
 */
export interface ParagraphBlock {
  /**
   * Discriminator for paragraph blocks.
   */
  type: 'paragraph';
  /**
   * Paragraph text content.
   */
  text: string;
}

/**
 * Content block for section headings.
 */
export interface HeadingBlock {
  /**
   * Discriminator for heading blocks.
   */
  type: 'heading';
  /**
   * Supported heading level.
   */
  level: 2 | 3;
  /**
   * Heading text content.
   */
  text: string;
}

/**
 * Content block for quoted text.
 */
export interface QuoteBlock {
  /**
   * Discriminator for quote blocks.
   */
  type: 'quote';
  /**
   * Quoted text content.
   */
  text: string;
  /**
   * Optional citation for the quote.
   */
  cite?: string;
}

/**
 * Content block for images.
 */
export interface ImageBlock {
  /**
   * Discriminator for image blocks.
   */
  type: 'image';
  /**
   * Source URL of the image.
   */
  src: string;
  /**
   * Alternative text for accessibility.
   */
  alt: string;
  /**
   * Optional image caption.
   */
  caption?: string;
}

/**
 * Union of all supported blog content block types.
 */
export type BlogContentBlock = ParagraphBlock | HeadingBlock | QuoteBlock | ImageBlock;

/**
 * Summary metadata for a blog post.
 */
export interface BlogPostSummary {
  /**
   * Unique identifier for the post.
   */
  id: string;
  /**
   * URL-friendly slug for the post.
   */
  slug: string;
  /**
   * Post title.
   */
  title: string;
  /**
   * Short summary excerpt of the post.
   */
  excerpt: string;
  /**
   * Cover image URL.
   */
  coverImage: string;
  /**
   * Publication timestamp as a string.
   */
  publishedAt: string;
  /**
   * Estimated reading duration in minutes.
   */
  readingMinutes: number;
  /**
   * Category assigned to the post.
   */
  category: BlogCategory;
  /**
   * Author of the post.
   */
  author: BlogAuthor;
  /**
   * Whether the post is featured.
   */
  featured: boolean;
}

/**
 * Complete blog post including content blocks.
 */
export interface BlogPost extends BlogPostSummary {
  /**
   * Rich content blocks for the post body.
   */
  content: BlogContentBlock[];
}

/**
 * Navigation item used in blog-related menus.
 */
export interface BlogNavigationItem {
  /**
   * Text label shown to users.
   */
  label: string;
  /**
   * Destination URL or path.
   */
  href: string;
}

/**
 * Image metadata that can adapt to different display sizes.
 */
export interface ResponsiveImage {
  /**
   * Source URL of the image.
   */
  src: string;
  /**
   * Alternative text for accessibility.
   */
  alt: string;
  /**
   * Optional intrinsic image width in pixels.
   */
  width?: number;
  /**
   * Optional intrinsic image height in pixels.
   */
  height?: number;
}

