/**
 * Converts a full blog post into its summary representation.
 *
 * @param post - Full post to convert.
 * @returns The summary metadata for the provided post.
 */
function toSummary(post: BlogPost): BlogPostSummary {
  const summary: BlogPostSummary = {
    id: post.id,
    slug: post.slug,
    title: post.title,
    excerpt: post.excerpt,
    coverImage: post.coverImage,
    publishedAt: post.publishedAt,
    readingMinutes: post.readingMinutes,
    category: post.category,
    author: post.author,
    featured: post.featured,
  };

  return summary;
}

/**
 * Parses an ISO-like timestamp string into epoch milliseconds.
 * Invalid values are treated as the oldest possible date.
 *
 * @param value - Date string to parse.
 * @returns Parsed epoch milliseconds or {@link Number.NEGATIVE_INFINITY} when invalid.
 */
function toEpoch(value: string): number {
  const epoch: number = Date.parse(value);
  return Number.isNaN(epoch) ? Number.NEGATIVE_INFINITY : epoch;
}

/**
 * Returns featured posts ordered from newest to oldest.
 *
 * @param limit - Optional maximum number of posts to return. Non-positive values return an empty list.
 * @returns Featured post summaries.
 */
export function getFeaturedPosts(limit?: number): BlogPostSummary[] {
  if (typeof limit === 'number' && limit <= 0) {
    return [];
  }

  const featuredPosts: BlogPost[] = blogPosts
    .filter((post: BlogPost): boolean => post.featured)
    .sort((left: BlogPost, right: BlogPost): number => toEpoch(right.publishedAt) - toEpoch(left.publishedAt));

  const summaries: BlogPostSummary[] = featuredPosts.map((post: BlogPost): BlogPostSummary => toSummary(post));

  if (typeof limit === 'number') {
    return summaries.slice(0, limit);
  }

  return summaries;
}

/**
 * Returns summaries for all posts ordered from newest to oldest.
 *
 * @returns All post summaries.
 */
export function getAllPostSummaries(): BlogPostSummary[] {
  return [...blogPosts]
    .sort((left: BlogPost, right: BlogPost): number => toEpoch(right.publishedAt) - toEpoch(left.publishedAt))
    .map((post: BlogPost): BlogPostSummary => toSummary(post));
}

/**
 * Finds a post by its slug.
 *
 * @param slug - Slug to search for.
 * @returns The matching post, or {@code null} when none is found or slug is empty.
 */
export function getPostBySlug(slug: string): BlogPost | null {
  const normalizedSlug: string = slug.trim();
  if (normalizedSlug.length === 0) {
    return null;
  }

  const found: BlogPost | undefined = blogPosts.find(
    (post: BlogPost): boolean => post.slug === normalizedSlug,
  );

  return found ?? null;
}

/**
 * Returns related posts for a given post and category, ordered from newest to oldest.
 *
 * @param postId - The source post identifier to exclude from results.
 * @param categorySlug - Category slug used to match related posts.
 * @param limit - Optional maximum number of related posts to return. Non-positive values return an empty list.
 * @returns Related post summaries.
 */
export function getRelatedPosts(
  postId: string,
  categorySlug: string,
  limit?: number,
): BlogPostSummary[] {
  if (typeof limit === 'number' && limit <= 0) {
    return [];
  }

  const normalizedCategorySlug: string = categorySlug.trim();
  if (normalizedCategorySlug.length === 0) {
    return [];
  }

  const relatedPosts: BlogPostSummary[] = blogPosts
    .filter(
      (post: BlogPost): boolean =>
        post.id !== postId && post.category.slug === normalizedCategorySlug,
    )
    .sort((left: BlogPost, right: BlogPost): number => toEpoch(right.publishedAt) - toEpoch(left.publishedAt))
    .map((post: BlogPost): BlogPostSummary => toSummary(post));

  if (typeof limit === 'number') {
    return relatedPosts.slice(0, limit);
  }

  return relatedPosts;
}

/**
 * Formats an ISO date string into a locale-aware display date.
 *
 * If the input cannot be parsed as a valid date, the original input string
 * is returned unchanged.
 *
 * @param isoDate - The ISO date string to format.
 * @param locale - Optional BCP 47 locale string used for formatting.
 * @returns A formatted display date, or the original input when invalid.
 */
export function formatDisplayDate(isoDate: string, locale?: string): string {
  const date: Date = new Date(isoDate);
  if (Number.isNaN(date.getTime())) {
    return isoDate;
  }

  try {
    return new Intl.DateTimeFormat(locale, {
      year: "numeric",
      month: "short",
      day: "numeric",
    }).format(date);
  } catch {
    return new Intl.DateTimeFormat(undefined, {
      year: "numeric",
      month: "short",
      day: "numeric",
    }).format(date);
  }
}

/**
 * Formats a reading time value in minutes.
 *
 * Values less than or equal to 1 are displayed as "1 min read".
 * Non-finite or negative values are clamped to 1 minute.
 *
 * @param minutes - The estimated reading time in minutes.
 * @returns A human-readable reading time string.
 */
export function formatReadingTime(minutes: number): string {
  const normalized: number = Number.isFinite(minutes) ? minutes : 1;
  const roundedUp: number = Math.ceil(normalized);
  const safeMinutes: number = Math.max(1, roundedUp);

  if (safeMinutes === 1) {
    return "1 min read";
  }

  return `${safeMinutes} min read`;
}

/**
 * Builds the canonical post href from a slug.
 *
 * The slug is trimmed, leading slashes are removed, and duplicate slashes
 * within the slug are normalized to a single slash.
 *
 * @param slug - The post slug.
 * @returns A normalized post href in the form "/blog/{slug}".
 */
export function buildPostHref(slug: string): string {
  const trimmed: string = slug.trim();
  const withoutLeadingSlashes: string = trimmed.replace(/^\/+/, "");
  const normalizedInternalSlashes: string = withoutLeadingSlashes.replace(/\/{2,}/g, "/");
  return `/blog/${normalizedInternalSlashes}`;
}

/**
 * Joins class names into a single space-separated string, omitting falsy
 * non-string values and empty strings.
 *
 * @param classes - Class name values to combine.
 * @returns A normalized class name string.
 */
export function cx(...classes: Array<string | false | null | undefined>): string {
  const filtered: string[] = classes.filter((value: string | false | null | undefined): value is string => {
    return typeof value === "string" && value.trim() !== "";
  });

  return filtered.join(" ");
}

/* Apple-inspired responsive blog UI */

:root {
  --apple-bg: #f5f5f7;
  --apple-surface: #ffffff;
  --apple-surface-muted: #fbfbfd;
  --apple-text: #1d1d1f;
  --apple-text-muted: #6e6e73;
  --apple-border: #d2d2d7;
  --apple-accent: #0071e3;
  --apple-accent-hover: #0077ed;
  --apple-shadow-sm: 0 8px 24px rgba(0, 0, 0, 0.06);
  --apple-shadow-md: 0 14px 34px rgba(0, 0, 0, 0.08);
  --apple-radius-lg: 22px;
  --apple-radius-md: 14px;
  --apple-radius-sm: 10px;
  --apple-max-width: 1120px;
}

* {
  box-sizing: border-box;
}

