  z-index: 40;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  max-width: var(--apple-max-width);
  margin: 0 auto;
  padding: 0.95rem 1.25rem;
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  background: rgba(245, 245, 247, 0.84);
  border-bottom: 1px solid rgba(210, 210, 215, 0.7);
}

.apple-blog-nav__brand {
  margin: 0;
  color: var(--apple-text);
  font-size: 1.05rem;
  font-weight: 650;
  letter-spacing: -0.01em;
}

.apple-blog-nav__links {
  display: flex;
  align-items: center;
  gap: 0.7rem;
