import { describe, it, expect } from "../node_modules/vitest";
import {
  formatDisplayDate,
  formatReadingTime,
  buildPostHref,
  cx,
} from "./blogFormatters";

describe("formatDisplayDate", (): void => {
  it("formats a valid ISO date using the provided locale", (): void => {
    const isoDate: string = "2024-01-15T00:00:00.000Z";

    const result: string = formatDisplayDate(isoDate, "en-US");

    expect(result).toBe("Jan 15, 2024");
  });

  it("returns original string when date is invalid", (): void => {
    const isoDate: string = "not-a-date";

    const result: string = formatDisplayDate(isoDate, "en-US");

    expect(result).toBe(isoDate);
  });

  it("uses default locale formatting when locale is omitted", (): void => {
    const isoDate: string = "2024-01-15T00:00:00.000Z";
    const expected: string = new Intl.DateTimeFormat(undefined, {
      year: "numeric",
      month: "short",
      day: "numeric",
    }).format(new Date(isoDate));

    const result: string = formatDisplayDate(isoDate);

    expect(result).toBe(expected);
  });

  it("falls back to default locale when locale is invalid", (): void => {
    const isoDate: string = "2024-01-15T00:00:00.000Z";
    const expected: string = new Intl.DateTimeFormat(undefined, {
      year: "numeric",
      month: "short",
      day: "numeric",
    }).format(new Date(isoDate));

    const result: string = formatDisplayDate(isoDate, "bad_locale_tag");

    expect(result).toBe(expected);
  });
});

describe("formatReadingTime", (): void => {
  it("returns singular label for 1 minute", (): void => {
    expect(formatReadingTime(1)).toBe("1 min read");
  });

  it("returns singular label for values less than or equal to 1", (): void => {
    expect(formatReadingTime(0.2)).toBe("1 min read");
    expect(formatReadingTime(0)).toBe("1 min read");
  });

  it("rounds fractional values up", (): void => {
    expect(formatReadingTime(2.1)).toBe("3 min read");
  });

  it("clamps negative values to 1 minute", (): void => {
    expect(formatReadingTime(-5)).toBe("1 min read");
  });

  it("clamps non-finite values to 1 minute", (): void => {
    expect(formatReadingTime(Number.NaN)).toBe("1 min read");
    expect(formatReadingTime(Number.POSITIVE_INFINITY)).toBe("1 min read");
    expect(formatReadingTime(Number.NEGATIVE_INFINITY)).toBe("1 min read");
  });
});

describe("buildPostHref", (): void => {
  it("builds href for a simple slug", (): void => {
    expect(buildPostHref("my-post")).toBe("/blog/my-post");
  });

  it("trims whitespace and removes leading slashes", (): void => {
    expect(buildPostHref("   ///guides/typescript   ")).toBe("/blog/guides/typescript");
  });

  it("normalizes duplicate internal slashes", (): void => {
    expect(buildPostHref("posts//2024///intro")).toBe("/blog/posts/2024/intro");
  });

  it("returns blog root suffix when slug is empty after trim", (): void => {
    expect(buildPostHref("   ")).toBe("/blog/");
  });
});

describe("cx", (): void => {
  it("joins class names with spaces", (): void => {
    expect(cx("btn", "btn-primary", "active")).toBe("btn btn-primary active");
  });

  it("omits false, null, undefined, and empty strings", (): void => {
    expect(cx("btn", false, null, undefined, "", "primary")).toBe("btn primary");
  });

  it("omits whitespace-only strings", (): void => {
    expect(cx("card", "   ", "shadow")).toBe("card shadow");
  });

  it("returns empty string when all entries are omitted", (): void => {
    expect(cx(false, null, undefined, "", "   ")).toBe("");
  });
});
